static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GemmDivideSumScalingCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);     // x: [batch, input]
    const gert::Shape* w_shape = context->GetInputShape(1);     // weight: [hidden, input]
    if (x_shape == nullptr || w_shape == nullptr) {
        return ge::GRAPH_FAILED;
    }

    uint64_t batchSize  = (x_shape->GetOriginShape().GetDimNum() >= 1) ? x_shape->GetOriginShape().GetDim(0) : 1;
    uint64_t inputSize  = (x_shape->GetOriginShape().GetDimNum() >= 2) ? x_shape->GetOriginShape().GetDim(1) : 1;
    uint64_t hiddenSize = (w_shape->GetOriginShape().GetDimNum() >= 1) ? w_shape->GetOriginShape().GetDim(0) : 1;

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_batchSize(static_cast<uint32_t>(batchSize));
    tiling.set_inputSize(static_cast<uint32_t>(inputSize));
    tiling.set_hiddenSize(static_cast<uint32_t>(hiddenSize));
    tiling.set_segLen(SEG_LEN);
    uint32_t rowsPerBlock = static_cast<uint32_t>(batchSize / BLOCK_DIM);
    if (rowsPerBlock == 0) rowsPerBlock = 1;
    tiling.set_rowsPerBlock(rowsPerBlock);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

